      "Solution acide tartrique			6g",
      "Fraises des bois fraîches		75g/500g de confiture",
      "Faire chauffer l’eau, la moitié sur sucre, puis une fois tiède ajouter l’autre moitié du sucre avec la pectine et cuire à 120°c. Verser les fraises des bois surgelées et les fraises surgelées sur le sucre cuit et cuire jusqu’à 104°c en mélangeant sans cesse. Ajouter l’acide, bien mélanger, passer à travers un bac de koma (crible) puis débarrasser et laisser refroidir. Ecraser grossièrement les fraises des bois fraîches à la cuillère avant de les ajouter à la confiture froide. Information : solution acide tartrique : 50% acide et 50% d’eau.",
